220	interface CategoriesSidebarProps {
221	  activeCategory: string | null;
222	  onSelectCategory: (catId: string | null) => void;
223	}
224	
225	export const CategoriesSidebar: React.FC<CategoriesSidebarProps> = ({
226	  activeCategory,
227	  onSelectCategory,
228	}) => {
229	  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
230	  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
231	  const contentRef = useRef<HTMLDivElement>(null);
232	  const patternContentRef = useRef<HTMLDivElement>(null);
233	
234	  const [thumbHeight, setThumbHeight] = useState(40);
235	  const [thumbTop, setThumbTop] = useState(8);
236	  const [hasScroll, setHasScroll] = useState(false);
237	  const [isDragging, setIsDragging] = useState(false);
238	
239	  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
240	  const [patternThumbTop, setPatternThumbTop] = useState(8);
241	  const [hasPatternScroll, setHasPatternScroll] = useState(false);
242	  const [isPatternDragging, setIsPatternDragging] = useState(false);
243	
244	  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
245	  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
246	  const [previewActive, setPreviewActive] = useState(false);
247	
248	  const startYRef = useRef(0);
249	  const startScrollTopRef = useRef(0);
250	
251	  useEffect(() => {
252	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
253	      setPreviewActive(!!e.detail?.active);
254	    };
255	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
256	    return () => {
257	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
258	    };
259	  }, []);
260	
261	  const handleCategoryClick = (cat: CategoryItem) => {
262	    if (cat.disabled) {
263	      showSuccess("Bientôt disponible");
264	      return;
265	    }
266	    if (activeCategory === cat.id) {
267	      onSelectCategory(null);
268	    } else {
269	      onSelectCategory(cat.id);
270	    }
271	    setIsPatternPopupOpen(false);
272	  };
273	
274	  useEffect(() => {
275	    if (!activeCategory) return;
276	
277	    const activeButton = iconRefs.current[activeCategory];
278	    activeButton?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
279	  }, [activeCategory]);
280	
281	  const handleCategoriesWheel = (event: React.WheelEvent<HTMLDivElement>) => {
282	    if (!categoriesToolbarRef.current || event.deltaY === 0) return;
283	    event.preventDefault();
284	    categoriesToolbarRef.current.scrollBy({ left: event.deltaY, behavior: 'smooth' });
285	  };
286	
287	  const handleScroll = () => {
288	    if (!contentRef.current || isDragging) return;
289	    const { scrollTop, scrollHeight, clientHeight } = contentRef.current;
290	    if (scrollHeight <= clientHeight) {
291	      setHasScroll(false);
292	      return;
293	    }
294	    setHasScroll(true);
295	    
296	    const margin = 8;
297	    const trackHeight = clientHeight - (margin * 2);
298	    const calculatedHeight = Math.max(32, (clientHeight / scrollHeight) * trackHeight);
299	    
300	    const maxScrollTop = scrollHeight - clientHeight;
301	    const maxThumbTop = trackHeight - calculatedHeight;
302	    const calculatedTop = maxScrollTop > 0 ? margin + (scrollTop / maxScrollTop) * maxThumbTop : margin;
303	
304	    setThumbHeight(calculatedHeight);
305	    setThumbTop(calculatedTop);
306	  };
307	
308	  const handlePatternScroll = () => {
309	    if (!patternContentRef.current || isPatternDragging) return;
310	    const { scrollTop, scrollHeight, clientHeight } = patternContentRef.current;
311	    if (scrollHeight <= clientHeight) {
312	      setHasPatternScroll(false);
313	      return;
314	    }
315	    setHasPatternScroll(true);
316	    
317	    const margin = 8;
318	    const trackHeight = clientHeight - (margin * 2);
319	    const calculatedHeight = Math.max(32, (clientHeight / scrollHeight) * trackHeight);
320	    
321	    const maxScrollTop = scrollHeight - clientHeight;
322	    const maxThumbTop = trackHeight - calculatedHeight;
323	    const calculatedTop = maxScrollTop > 0 ? margin + (scrollTop / maxScrollTop) * maxThumbTop : margin;
324	
325	    setPatternThumbHeight(calculatedHeight);
326	    setPatternThumbTop(calculatedTop);
327	  };
328	
329	  const handleMouseDown = (e: React.MouseEvent) => {
330	    setIsDragging(true);
331	    startYRef.current = e.clientY;
332	    if (contentRef.current) {
333	      startScrollTopRef.current = contentRef.current.scrollTop;
334	    }
335	    document.addEventListener('mousemove', handleMouseMove);
336	    document.addEventListener('mouseup', handleMouseUp);
337	    e.preventDefault();
338	  };
339	
340	  const handleMouseMove = (e: MouseEvent) => {
341	    if (!contentRef.current) return;
342	    const deltaY = e.clientY - startYRef.current;
343	    const { scrollHeight, clientHeight } = contentRef.current;
344	    const margin = 8;
345	    const trackHeight = clientHeight - (margin * 2);
346	    const maxThumbTop = trackHeight - thumbHeight;
347	    const maxScrollTop = scrollHeight - clientHeight;
348	
349	    if (maxThumbTop > 0) {
350	      const scrollRatio = deltaY / maxThumbTop;
351	      const newScrollTop = Math.max(0, Math.min(maxScrollTop, startScrollTopRef.current + scrollRatio * maxScrollTop));
352	      contentRef.current.scrollTop = newScrollTop;
353	      
354	      const calculatedTop = margin + (newScrollTop / maxScrollTop) * maxThumbTop;
355	      setThumbTop(calculatedTop);
356	    }
357	  };
358	
359	  const handleMouseUp = () => {
360	    setIsDragging(false);
361	    document.removeEventListener('mousemove', handleMouseMove);
362	    document.removeEventListener('mouseup', handleMouseUp);
363	  };
364	
365	  const handlePatternMouseDown = (e: React.MouseEvent) => {
366	    setIsPatternDragging(true);
367	    startYRef.current = e.clientY;
368	    if (patternContentRef.current) {
369	      startScrollTopRef.current = patternContentRef.current.scrollTop;
370	    }
371	    document.addEventListener('mousemove', handlePatternMouseMove);
372	    document.addEventListener('mouseup', handlePatternMouseUp);
373	    e.preventDefault();
374	  };
375	
376	  const handlePatternMouseMove = (e: MouseEvent) => {
377	    if (!patternContentRef.current) return;
378	    const deltaY = e.clientY - startYRef.current;
379	    const { scrollHeight, clientHeight } = patternContentRef.current;
380	    const margin = 8;
381	    const trackHeight = clientHeight - (margin * 2);
382	    const maxThumbTop = trackHeight - patternThumbHeight;
383	    const maxScrollTop = scrollHeight - clientHeight;
384	
385	    if (maxThumbTop > 0) {
386	      const scrollRatio = deltaY / maxThumbTop;
387	      const newScrollTop = Math.max(0, Math.min(maxScrollTop, startScrollTopRef.current + scrollRatio * maxScrollTop));
388	      patternContentRef.current.scrollTop = newScrollTop;
389	      
390	      const calculatedTop = margin + (newScrollTop / maxScrollTop) * maxThumbTop;
391	      setPatternThumbTop(calculatedTop);
392	    }
393	  };
394	
395	  const handlePatternMouseUp = () => {
396	    setIsPatternDragging(false);
397	    document.removeEventListener('mousemove', handlePatternMouseMove);
398	    document.removeEventListener('mouseup', handlePatternMouseUp);
399	  };
400	
401	  useEffect(() => {
402	    if (activeCategory) {
403	      setTimeout(handleScroll, 50);
404	    } else {
405	      setIsPatternPopupOpen(false);
406	    }
407	  }, [activeCategory]);
408	
409	  useEffect(() => {
410	    if (isPatternPopupOpen) {
411	      setTimeout(handlePatternScroll, 50);
412	    }
413	  }, [isPatternPopupOpen]);
414	
415	  const activeCatData = CATEGORIES.find(c => c.id === activeCategory);
416	
417	  return (
418	    <>
419	      <div className={styles.leftSidebarContainer} data-apex-chrome-panel>
420	        <AnimatePresence>
421	          {!previewActive && (
422	            <motion.div
423	              ref={categoriesToolbarRef}
424	              className={styles.categoriesToolbar}
425	              onWheel={handleCategoriesWheel}
426	              initial={{ opacity: 0, x: -20 }}
427	              animate={{ opacity: 1, x: 0 }}
428	              exit={{ opacity: 0, x: -20 }}
429	              transition={{
430	                opacity: { duration: 0.9, ease: 'linear' },
431	                x: { duration: 0.9, ease: 'easeInOut' },
432	              }}
433	            >
434	              {CATEGORIES.map((cat) => {
435	                const isActive = activeCategory === cat.id;
436	                return (
437	                  <CustomTooltip
438	                    key={cat.id}
439	                    content="Arrive bientôt"
440	                    description={cat.description}
441	                  >
442	                    <button
443	                      ref={(el) => { iconRefs.current[cat.id] = el; }}
444	                      className={clsx(styles.categoryButton, {
445	                        [styles.active]: isActive,
446	                        [styles.disabledButton]: true
447	                      })}
448	                      disabled
449	                    >
450	                      {cat.icon}
451	                      <span className={styles.categoryLabel}>{cat.label}</span>
452	                    </button>
453	                  </CustomTooltip>
454	                );
455	              })}
456	            </motion.div>
457	          )}
458	        </AnimatePresence>
459	      </div>
460	
461	      <AnimatePresence>
462	        {activeCatData && !activeCatData.disabled && (
463	          <>
464	            <motion.div 
465	              className={styles.fusionMenuContainer}
466	              initial={{ opacity: 0, scale: 0.95, x: -10, y: 20 }}
467	              animate={{ opacity: 1, scale: 1, x: 0, y: 0 }}
468	              exit={{ opacity: 0, scale: 0.95, x: -10, y: 20 }}
469	              transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
470	            >
471	              <div 
472	                ref={contentRef}
473	                className={styles.fusionMenuContent}
474	                onScroll={handleScroll}
475	              >
476	                {activeCatData.sections.map((section, idx) => (
477	                  <div key={idx} className={styles.sectionGroup}>
478	                    <h4 className={styles.sectionTitle}>{section.title}</h4>
479	                    <ul className={styles.itemsList}>
480	                      {section.items.map((item, iIdx) => (
481	                        <CustomTooltip key={iIdx} content={item.label} description={item.description}>
482	                          <li 
483	                            className={clsx(styles.itemRow, { [styles.clickableRow]: item.isPatternDropdown })}
484	                            onClick={() => {
485	                              if (item.isPatternDropdown) {
486	                                setIsPatternPopupOpen(!isPatternPopupOpen);
487	                              }
488	                            }}
489	                          >
490	                            <span className={styles.itemName}>
491	                              {item.isPatternDropdown ? `Motif de remplissage (${selectedPattern})` : item.label}
492	                            </span>
493	                            {item.isPatternDropdown ? (
494	                              <ChevronDown size={14} className="shrink-0 text-[#00f0ff] -rotate-90 ml-2" />
495	                            ) : (
496	                              <input 
497	                                type="text" 
498	                                defaultValue={item.defaultValue} 
499	                                className={styles.itemInput} 
500	                              />
501	                            )}
502	                          </li>
503	                        </CustomTooltip>
504	                      ))}
505	                    </ul>
506	                  </div>
507	                ))}
508	              </div>
509	
510	              {hasScroll && (
511	                <div 
512	                  className={clsx(styles.externalScrollThumb, { [styles.dragging]: isDragging })}
513	                  onMouseDown={handleMouseDown}
514	                  style={{
515	                    height: `${thumbHeight}px`,
516	                    top: `${thumbTop}px`
517	                  }}
518	                />
519	              )}
520	            </motion.div>
521	
522	            {/* Pattern popup window next to the menu */}
523	            <AnimatePresence>
524	              {isPatternPopupOpen && (
525	                <motion.div
526	                  className={styles.patternPopup}
527	                  initial={{ opacity: 0, scale: 0.95, x: -10 }}
528	                  animate={{ opacity: 1, scale: 1, x: 0 }}
529	                  exit={{ opacity: 0, scale: 0.95, x: -10 }}
530	                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
531	                >
532	                  <div 
533	                    ref={patternContentRef}
534	                    className={styles.patternPopupContent}
535	                    onScroll={handlePatternScroll}
536	                  >
537	                    <div className={styles.sectionGroup}>
538	                      <h4 className={styles.sectionTitle}>Motifs de remplissage</h4>
539	                      <ul className={styles.itemsList}>
540	                        {INFILL_PATTERNS.map((pat, pIdx) => {
541	                          const isSelected = selectedPattern === pat.name;
542	                          return (
543	                            <CustomTooltip key={pIdx} content={pat.name} description={pat.description} key-override={pat.name}>
544	                              <li 
545	                                className={clsx(styles.patternItem, { [styles.activePattern]: isSelected })}
546	                                onClick={() => {
547	                                  setSelectedPattern(pat.name);
548	                                  setIsPatternPopupOpen(false);
549	                                }}
550	                              >
551	                                <span className={styles.itemName}>{pat.name}</span>
552	                                {isSelected && <Check size={14} className="text-[#00f0ff] shrink-0" />}
