225	export const CategoriesSidebar: React.FC<CategoriesSidebarProps> = ({
226	  activeCategory,
227	  onSelectCategory,
228	}) => {
229	  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
230	  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
231	  const contentRef = useRef<HTMLDivElement>(null);
232	  const patternContentRef = useRef<HTMLDivElement>(null);
233	
234	  const [thumbHeight, setThumbHeight] = useState(40);
235	  const [thumbTop, setThumbTop] = useState(8);
236	  const [hasScroll, setHasScroll] = useState(false);
237	  const [isDragging, setIsDragging] = useState(false);
238	
239	  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
240	  const [patternThumbTop, setPatternThumbTop] = useState(8);
241	  const [hasPatternScroll, setHasPatternScroll] = useState(false);
242	  const [isPatternDragging, setIsPatternDragging] = useState(false);
243	
244	  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
245	  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
246	  const [previewActive, setPreviewActive] = useState(false);
247	
248	  const startYRef = useRef(0);
249	  const startScrollTopRef = useRef(0);
250	
251	  useEffect(() => {
252	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
253	      setPreviewActive(!!e.detail?.active);
254	    };
255	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
256	    return () => {
257	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
258	    };
259	  }, []);
260	
261	  const handleCategoryClick = (cat: CategoryItem) => {
262	    if (cat.disabled) {
263	      showSuccess("Bientôt disponible");
264	      return;
265	    }
266	    if (activeCategory === cat.id) {
267	      onSelectCategory(null);
268	    } else {
