"use client";

import React, { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useGCodePreview } from '@/hooks/use-gcode-preview';
import styles from './GCodePreview.module.scss';

/**
 * Interface de l'espace Prévisualisation. Toute la logique (chargement, dépôt de fichier,
 * lecture, trajets à vide) est dans `useGCodePreview` ; les deux panneaux ci-dessous sont pour
 * l'instant des coquilles vides (contenu à brancher plus tard).
 *
 * À l'entrée dans l'espace, le panneau du haut naît par le même effet "mitose" que le panneau de
 * catégorie de CategoriesSidebar : une bulle qui s'étire, développe un col métaball, puis se
 * scinde pour engendrer le panneau du bas — sauf qu'ici la division n'a lieu qu'une fois par
 * entrée dans l'espace, et les deux panneaux restent affichés en permanence tant qu'on y reste
 * (pas de fermeture symétrique comme le menu de catégorie).
 */

const GOO_DURATION = 620;

interface GCodePreviewProps {
  /** Espace Prévisualisation affiché. */
  active: boolean;
}

export const GCodePreview: React.FC<GCodePreviewProps> = ({ active }) => {
  // Appelé même quand l'espace est masqué, pour garder le fichier et la position de lecture.
  const preview = useGCodePreview(active);
  void preview;

  // null tant que la mitose n'a jamais eu lieu ; passe à 'dividing' à chaque entrée dans l'espace
  // (et seulement à ce moment — pas de rejeu au sein d'une même visite).
  const [gooPhase, setGooPhase] = useState<'dividing' | null>(null);
  const [panelsBorn, setPanelsBorn] = useState(false);
  const gooTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wasActiveRef = useRef(false);

  useEffect(() => {
    if (active && !wasActiveRef.current) {
      // Nouvelle entrée dans l'espace : rejoue la mitose depuis le panneau vide.
      setPanelsBorn(false);
      setGooPhase('dividing');
      if (gooTimeoutRef.current) clearTimeout(gooTimeoutRef.current);
      gooTimeoutRef.current = setTimeout(() => {
        setPanelsBorn(true);
        setGooPhase(null);
      }, GOO_DURATION);
    } else if (!active) {
      // En quittant l'espace, on repart de l'état initial pour que la mitose se rejoue à la
      // prochaine entrée plutôt que de simplement ré-fondre les panneaux déjà séparés.
      if (gooTimeoutRef.current) {
        clearTimeout(gooTimeoutRef.current);
        gooTimeoutRef.current = null;
      }
      setGooPhase(null);
      setPanelsBorn(false);
    }
    wasActiveRef.current = active;
  }, [active]);

  useEffect(() => () => {
    if (gooTimeoutRef.current) clearTimeout(gooTimeoutRef.current);
  }, []);

  if (!active) return null;

