        setModelStatus(null);
        return;
      }

      setModelStatus({
        name: event.detail.name,
        dimensions: event.detail.dimensions ?? null,
      });
    };

    const handleModelImported = (event: CustomEvent<File>) => {
      if (event.detail?.name) {
        setModelStatus({ name: event.detail.name, dimensions: null });
      }
    };

