// Calque d'interface au-dessus du viewport (le rendu 3D reste celui de Viewport3D) : il laisse
// passer la souris vers la caméra, seuls ses enfants la captent. Sous le rideau de transition
// (SpaceTransitionOverlay, z-index 30) et sous la barre d'aide de TopRightMenu (z-index 1000).
.container {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;

  > * {
    pointer-events: auto;
  }
}

// Filtre "goo" dédié à la mitose des panneaux de Prévisualisation (même recette que celui de
// CategoriesSidebar : flou fort + recontraste alpha pour souder visuellement deux formes tant
// qu'elles se chevauchent). Un id séparé pour ne pas dépendre du montage de CategoriesSidebar,
// qui est démonté en Prévisualisation.
.gooSvg {
  position: absolute;
  width: 0;
  height: 0;
}

// Calque de mitose : la pilule vide et le panneau naissant, avant que la vraie mise en page
// (panelUpper / panelLower ci-dessous) ne prenne le relais une fois séparés.
.gooStage {
  position: fixed;
  left: 24px;
  top: 96px;
  width: 344px;
  height: 800px;
  z-index: 1000;
  pointer-events: none;
  filter: url('#apex-preview-goo');
}

.gooBlobUpper {
  position: absolute;
  top: 0;
  left: 0;
  width: 344px;
  height: 524px;
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.92);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
}

.gooBlobNeck {
  position: absolute;
  top: 484px;
  left: 50%;
  width: 140px;
  height: 40px;
  margin-left: -70px;
  border-radius: 999px;
  background: rgba(10, 15, 26, 0.92);
  transform-origin: center top;
}

.gooBlobLower {
  position: absolute;
  top: 524px;
  left: 50%;
  width: 344px;
  height: 250px;
  margin-left: -172px;
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.92);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
  transform-origin: center top;
}

// Base commune des deux panneaux réels — même traitement glassmorphism que les autres panneaux
// fixes de l'app (cf. .fusionMenuContainer dans CategoriesSidebar.module.scss).
%previewPanelBase {
  position: fixed;
  left: 24px;
  width: 344px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 20px;
  z-index: 1000;
  overflow: hidden;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

// Rectangle du haut : infos sur le G-code chargé (contenu à brancher plus tard).
.panelUpper {
  @extend %previewPanelBase;
  top: 96px;
  height: 524px;
}

// Rectangle du bas, né par mitose du premier (contenu à brancher plus tard).
.panelLower {
  @extend %previewPanelBase;
  top: 636px;
  height: 250px;
}

