  z-index: 1000;
  pointer-events: none;
  filter: url('#apex-preview-goo');
}

.previewBlobPill {
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.92);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
}

.previewBlobNeck {
  position: absolute;
  top: 484px;
  left: 50%;
  width: 140px;
  height: 40px;
  margin-left: -70px;
  border-radius: 999px;
  background: rgba(10, 15, 26, 0.92);
  transform-origin: center top;
}

.previewBlobLower {
  position: absolute;
  top: 524px;
  left: 0;
  width: 344px;
