// Mitose de l'espace Prévisualisation (cf. previewGooPhase dans CategoriesSidebar.tsx) : la vraie
// pilule s'étire pour devenir le panneau du haut, qui engendre le panneau du bas. `previewGooStage`
// couvre tout l'espace occupé par les deux panneaux finaux (haut + cou + bas), positionné en
// `fixed` avec la même origine que `.leftSidebarContainer` (left:24) pour que ses coordonnées
// relatives coïncident avec celles de la vraie pilule.
.previewGooStage {
  position: fixed;
  left: 24px;
  top: 96px;
  width: 344px;
  height: 790px; // du sommet du panneau du haut (96) au bas du panneau du bas (636 + 250 - 96)
  z-index: 1000;
  pointer-events: none;
  filter: url('#apex-preview-goo');
}

.previewBlobPill {
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.92);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
}

.previewBlobNeck {
  position: absolute;
  top: 484px;
  left: 50%;
  width: 140px;
  height: 40px;
  margin-left: -70px;
  border-radius: 999px;
  background: rgba(10, 15, 26, 0.92);
  transform-origin: center top;
}

.previewBlobLower {
  position: absolute;
  top: 524px;
  left: 0;
  width: 344px;
  height: 250px;
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.92);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4);
  transform-origin: top center;
}

// Base commune des deux panneaux réels de Prévisualisation — même traitement glassmorphism que
// .fusionMenuContainer ci-dessous.
%previewPanelBase {
  position: fixed;
  left: 24px;
  width: 344px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 20px;
  z-index: 1000;
  overflow: hidden;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

// Panneau du haut : ce que la pilule devient (contenu à brancher plus tard).
.previewPanelUpper {
  @extend %previewPanelBase;

