export const CategoriesSidebar: React.FC<CategoriesSidebarProps> = ({
  activeCategory,
  onSelectCategory,
}) => {
  const iconRefs = useRef<{ [key: string]: HTMLButtonElement | null }>({});
  const categoriesToolbarRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const patternContentRef = useRef<HTMLDivElement>(null);

  const [thumbHeight, setThumbHeight] = useState(40);
  const [thumbTop, setThumbTop] = useState(8);
  const [hasScroll, setHasScroll] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const [patternThumbHeight, setPatternThumbHeight] = useState(40);
  const [patternThumbTop, setPatternThumbTop] = useState(8);
  const [hasPatternScroll, setHasPatternScroll] = useState(false);
  const [isPatternDragging, setIsPatternDragging] = useState(false);

  const [selectedPattern, setSelectedPattern] = useState<string>('Gyroïde');
  const [isPatternPopupOpen, setIsPatternPopupOpen] = useState(false);
  const [previewActive, setPreviewActive] = useState(false);

  // Transition "mitose" : au lieu d'un simple fondu, le panneau détaillé naît de la pilule de
  // catégories par un effet gluant (filtre SVG goo, cf. GooeyDefs plus bas) — les deux formes
  // se comportent comme des bulles qui fusionnent/se séparent le temps de la transition, avant
  // de redevenir des panneaux nets. `gooPhase` piloté par le cycle ouverture/fermeture ci-dessous :
  //  - 'dividing'  : la pilule s'étire vers le bas et engendre le panneau (ouverture)
  //  - 'merging'   : le panneau remonte se refondre dans la pilule (fermeture)
  //  - null        : hors transition, rendu normal (pas de filtre — le texte doit rester net)
  const [gooPhase, setGooPhase] = useState<'dividing' | 'merging' | null>(null);
  const gooTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const GOO_DURATION = 620;

  // Mitose de l'espace Prévisualisation : contrairement à celle du menu de catégorie, elle part
  // de la VRAIE pilule (jamais masquée dans cet espace, cf. le rendu plus bas) et ne se referme
  // jamais tant qu'on y reste. Deux temps STRICTEMENT séquentiels (jamais les deux à la fois) :
  //  - 'stretching' : la pilule s'étire seule jusqu'à devenir le panneau du haut (pas de division)
  //  - 'dividing'   : une fois stable, le panneau du haut engendre le panneau du bas
  // Se rejoue à chaque nouvelle entrée dans l'espace (pas au sein d'une même visite).
  const [previewGooPhase, setPreviewGooPhase] = useState<'stretching' | 'dividing' | null>(null);
  const [previewPanelsBorn, setPreviewPanelsBorn] = useState(false);
  const previewGooTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wasPreviewActiveRef = useRef(false);
  const STRETCH_DURATION = 500;
  const DIVIDE_DURATION = 550;

  const startYRef = useRef(0);
  const startScrollTopRef = useRef(0);

  useEffect(() => {
    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
      setPreviewActive(!!e.detail?.active);
    };
    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
    return () => {
      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
    };
  }, []);

  useEffect(() => {
    if (previewActive && !wasPreviewActiveRef.current) {
      // Nouvelle entrée dans l'espace Prévisualisation : rejoue la mitose depuis la pilule, en
      // deux temps strictement l'un après l'autre (jamais chevauchés) — cf. le commentaire sur
      // previewGooPhase plus haut.
      setPreviewPanelsBorn(false);
      setPreviewGooPhase('stretching');
      if (previewGooTimeoutRef.current) clearTimeout(previewGooTimeoutRef.current);
      previewGooTimeoutRef.current = setTimeout(() => {
        // Étape 1 terminée (pilule devenue panneau du haut) : étape 2 démarre seulement ici.
        setPreviewGooPhase('dividing');
        previewGooTimeoutRef.current = setTimeout(() => {
          setPreviewPanelsBorn(true);
          setPreviewGooPhase(null);
        }, DIVIDE_DURATION);
      }, STRETCH_DURATION);
    } else if (!previewActive) {
      if (previewGooTimeoutRef.current) {
        clearTimeout(previewGooTimeoutRef.current);
        previewGooTimeoutRef.current = null;
      }
      setPreviewGooPhase(null);
      setPreviewPanelsBorn(false);
    }
    wasPreviewActiveRef.current = previewActive;
  }, [previewActive]);

  useEffect(() => () => {
    if (previewGooTimeoutRef.current) clearTimeout(previewGooTimeoutRef.current);
  }, []);

  const handleCategoryClick = (cat: CategoryItem) => {
    if (cat.disabled) {
      showSuccess("Bientôt disponible");
      return;
    }
    setIsPatternPopupOpen(false);

    if (gooTimeoutRef.current) {
      clearTimeout(gooTimeoutRef.current);
      gooTimeoutRef.current = null;
    }

    if (activeCategory === cat.id) {
      // Fermeture : le panneau se refond dans la pilule (merging) avant de disparaître.
      setGooPhase('merging');
      gooTimeoutRef.current = setTimeout(() => {
        onSelectCategory(null);
        setGooPhase(null);
      }, GOO_DURATION);
    } else if (activeCategory === null) {
      // Ouverture depuis rien : la pilule enfante le panneau (dividing).
      setGooPhase('dividing');
      onSelectCategory(cat.id);
      gooTimeoutRef.current = setTimeout(() => setGooPhase(null), GOO_DURATION);
    } else {
      // Un panneau est déjà ouvert : simple substitution de contenu, pas de mitose.
      onSelectCategory(cat.id);
    }
  };

