import { mitosisPath, rectPath, stretchPath, type GlassRect } from '@/utils/liquidGlass';

// Géométrie des morphings, en px, dans le repère de la pilule (fixed, left 24 / top 212). Doit
// rester alignée sur CategoriesSidebar.module.scss (.leftSidebarContainer, .categoriesToolbar,
// .fusionMenuContainer, .previewPanelUpper/.previewPanelLower).
const PANEL_LEFT = 24;
const PILL_TOP = 212;
const PILL: GlassRect = { x: 0, y: 0, w: 293, h: 56, r: 20 };

const MENU_OFFSET_Y = 68; // .fusionMenuContainer : top 280
const MENU_W = 320;
const MENU_R = 16;
// Panneau (max-height 400) + la marge que prend le col en s'étirant avant de se rompre.
const MENU_STAGE_H = MENU_OFFSET_Y + 400 + 40;
const MENU_MORPH_MS = 700;

// Prévisualisation : panneau du haut sur toute la hauteur disponible, panneau du bas de hauteur
// fixe, le tout s'arrêtant à 236px du bas de l'écran (au-dessus de la barre d'aide).
const PREVIEW_W = 344;
const PREVIEW_R = 20;
const PREVIEW_GAP = 16;
const PREVIEW_LOWER_H = 250;
const PREVIEW_BOTTOM_MARGIN = 236;
const PREVIEW_UPPER_MIN_H = 120;
const PREVIEW_STRETCH_MS = 520;
const PREVIEW_HOLD_MS = 90; // temps mort entre l'étirement et la division : deux gestes distincts
const PREVIEW_DIVIDE_MS = 760;
const PREVIEW_MORPH_MS = PREVIEW_STRETCH_MS + PREVIEW_HOLD_MS + PREVIEW_DIVIDE_MS;

const previewGeometry = (viewportH: number) => {
  const upperH = Math.max(
    PREVIEW_UPPER_MIN_H,
    viewportH - PREVIEW_BOTTOM_MARGIN - PREVIEW_LOWER_H - PREVIEW_GAP - PILL_TOP,
  );
  const upper: GlassRect = { x: 0, y: 0, w: PREVIEW_W, h: upperH, r: PREVIEW_R };
  const lower: GlassRect = { x: 0, y: upperH + PREVIEW_GAP, w: PREVIEW_W, h: PREVIEW_LOWER_H, r: PREVIEW_R };
  // + marge pour le col qui s'étire avant la rupture.
  return { upper, lower, stageH: lower.y + lower.h + 40 };
};

