        transition={{ duration: GOO_DURATION / 1000, times: [0, 0.4, 1], ease: 'easeInOut' }}
        style={{ transformOrigin: 'top center' }}
      />
      <motion.div
        className={styles.gooBlobNeck}
        initial={gooPhase === 'dividing' ? { scaleX: 1, scaleY: 0.3, opacity: 1 } : { scaleX: 0.1, scaleY: 1.6, opacity: 0 }}
        animate={
          gooPhase === 'dividing'
            ? { scaleX: [1, 0.85, 0.35, 0.1], scaleY: [0.3, 1, 1.6, 1.6], opacity: [1, 1, 1, 0] }
            : { scaleX: [0.1, 0.35, 0.85, 1], scaleY: [1.6, 1.6, 1, 0.3], opacity: [0, 1, 1, 1] }
        }
        transition={{ duration: GOO_DURATION / 1000, times: [0, 0.35, 0.7, 1], ease: 'easeInOut' }}
      />
      <motion.div
        className={styles.gooBlobPanel}
        initial={gooPhase === 'dividing' ? { y: -30, scaleY: 0.15, opacity: 1 } : { y: 0, scaleY: 1, opacity: 1 }}
        animate={gooPhase === 'dividing' ? { y: 0, scaleY: 1, opacity: 1 } : { y: -30, scaleY: 0.15, opacity: 1 }}
        transition={{ duration: GOO_DURATION / 1000, ease: [0.65, 0, 0.35, 1] }}
      />
    </motion.div>
  )}
</AnimatePresence>

<AnimatePresence>
  {activeCatData && !activeCatData.disabled && (
    <>
      <motion.div
        className={styles.fusionMenuContainer}
        initial={{ opacity: 0, scale: 0.95, x: -10, y: 20 }}
        animate={{
          opacity: gooPhase === 'merging' ? 0 : 1,
          scale: 1,
          x: 0,
          y: 0,
        }}
        exit={{ opacity: 0, scale: 0.95, x: -10, y: 20 }}
        transition={
          gooPhase === 'dividing'
            ? { opacity: { delay: GOO_DURATION / 1000 - 0.18, duration: 0.18, ease: 'linear' } }
