.leftSidebarContainer {
  position: fixed;
  left: 24px;
  top: 212px;
  display: flex;
  flex-direction: column;
  z-index: 1000;
  pointer-events: none;
}

.categoriesToolbar {
  display: flex;
  flex-direction: row;
  width: 293px;
  max-width: 293px;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: smooth;
  gap: 6px;
  pointer-events: auto;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 8px;
  border-radius: 20px;

  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }

  > div {
    width: auto;
    flex: 0 0 auto;
  }
}

.categoryButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  min-width: 40px;
  height: 40px;
  padding: 0 12px;
  gap: 8px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  color: rgba(255, 255, 255, 0.7);
  cursor: pointer;
  border-radius: 12px;
  transition: all 0.2s ease;
  outline: none;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }

  &.active {
    background: rgba(0, 240, 255, 0.18);
    color: #00f0ff;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &.disabledButton {
    opacity: 0.35;
    cursor: not-allowed;
    pointer-events: none;
  }
}

