  align-items: center;
  gap: 6px;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: #00f0ff;
  font-size: 11px;
  padding: 4px 8px;
  transition: all 0.2s;
  max-width: 140px;
  pointer-events: none;
}

.dropdownText {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.patternPopup {
  position: fixed;
