  top: calc(50% - 180px);
  width: 320px;
  max-height: 400px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  z-index: 1003;
  display: flex;
  flex-direction: column;
  overflow: visible;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.patternPopupContent {
  padding: 16px;
  overflow-y: scroll;
  max-height: 400px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-radius: 16px;

  &::-webkit-scrollbar {
    width: 0px;
    background: transparent;
  }
}

.patternItem {
