file.content:
const activeCatData = CATEGORIES.find(c => c.id === activeCategory);

const previewGeo = previewGeometry(window.innerHeight);

return (
  <>
    <div className={styles.leftSidebarContainer} data-apex-chrome-panel>
      <AnimatePresence>
        {/* En Prévisualisation, la pilule reste montée (sans fond, cf. .morphing) jusqu'à ce que
            la mitose ait donné naissance aux deux panneaux, puis disparaît : elle EST devenue le
            panneau du haut. */}
        {(!previewActive || !previewPanelsBorn) && (
          <motion.div
            ref={categoriesToolbarRef}
            className={clsx(styles.categoriesToolbar, {
              [styles.morphing]: morphPhase !== null || previewMorphing,
            })}
            onWheel={handleCategoriesWheel}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{
              opacity: { duration: 0.9, ease: 'linear' },
              x: { duration: 0.9, ease: 'easeInOut' },
            }}
          >
            {CATEGORIES.map((cat) => {
              const isActive = activeCategory === cat.id;
              return (
                <CustomTooltip
                  key={cat.id}
                  content={cat.label}
                  description={cat.description}
                >
                  <button
                    ref={(el) => { iconRefs.current[cat.id] = el; }}
                    className={clsx(styles.categoryButton, {
                      [styles.active]: isActive,
                    })}
                    onClick={() => handleCategoryClick(cat)}
                  >
                    {cat.icon}
                    <span className={styles.categoryLabel}>{cat.label}</span>
                  </button>
                </CustomTooltip>
              );
            })}
          </motion.div>
        )}
      </AnimatePresence>
    </div>

    {/* Prévisualisation : la pilule s'étire en panneau du haut, puis celui-ci enfante le panneau
        du bas. Le verre animé part exactement de la géométrie de la pilule et finit exactement
        sur celle des deux panneaux ci-dessous, qui le remplacent à la dernière image. */}
    {previewActive && previewMorphing && (
      <LiquidGlassMorph
        left={PANEL_LEFT}
        top={PILL_TOP}
        width={PREVIEW_W}
        height={previewGeo.stageH}
        duration={PREVIEW_MORPH_MS}
        pathAt={previewPathAt}
        onDone={() => {
          setPreviewPanelsBorn(true);
          setPreviewMorphing(false);
        }}
      />
    )}

    {/* Panneaux de Prévisualisation, nés de la mitose : contenu à brancher plus tard. Pas
        d'animation d'entrée — leur verre est identique à la dernière image du morphing. */}
    <AnimatePresence>
      {previewActive && previewPanelsBorn && (
        <React.Fragment key="preview-panels">
          <motion.div
            className={styles.previewPanelUpper}
            initial={false}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3, ease: 'linear' }}
          />
          <motion.div
            className={styles.previewPanelLower}
            initial={false}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3, ease: 'linear' }}
          />
        </React.Fragment>
      )}
    </AnimatePresence>

    {/* Menu de catégorie : la pilule enfante le panneau (ouverture) ou le réabsorbe (fermeture,
        même timeline jouée à l'envers). */}
    {morphPhase && (
      <LiquidGlassMorph
        key={morphPhase}
        left={PANEL_LEFT}
        top={PILL_TOP}
        width={MENU_W}

