1	import React, { useLayoutEffect, useRef } from 'react';
2	import styles from './LiquidGlassMorph.module.scss';
3	
4	/**
5	 * Forme de verre animée : un unique élément en `backdrop-filter` (même verre que les panneaux,
6	 * cf. .fusionMenuContainer) dont la silhouette est redessinée à chaque image via `clip-path:
7	 * path(...)`. Le flou du fond reste ainsi un vrai flou CSS pendant tout le morphing — aucun
8	 * filtre SVG n'est appliqué au verre ni à un de ses ancêtres (un `filter`, une `opacity` < 1 ou un
9	 * `clip-path` sur un ancêtre isolerait le `backdrop-filter` du fond et le rendrait opaque).
10	 *
11	 * L'ombre portée est un calque séparé (frère, jamais ancêtre du verre) : la forme noircie, floutée
12	 * puis découpée à l'EXTÉRIEUR de la silhouette, exactement comme un `box-shadow` qui ne se dessine
13	 * jamais sous l'élément — sans quoi le verre, translucide, paraîtrait plus sombre que les vrais
14	 * panneaux au moment où ceux-ci prennent le relais.
15	 *
16	 * Les positions sont en px, en `position: fixed` ; `pathAt(t, dx, dy)` décrit la forme dans le
17	 * repère de la boîte (left, top), décalée de (dx, dy).
18	 */
19	
20	interface LiquidGlassMorphProps {
21	  left: number;
22	  top: number;
23	  width: number;
24	  height: number;
25	  /** Durée totale en ms. */
26	  duration: number;
27	  pathAt: (t: number, dx: number, dy: number) => string;
28	  /** Joue la timeline de t = 1 vers t = 0 (fusion plutôt que division, par exemple). */
29	  reverse?: boolean;
30	  onDone?: () => void;
31	}
32	
33	// Marge du calque d'ombre autour de la boîte, pour que le flou ne soit pas rogné.
34	const SHADOW_MARGIN = 64;
35	
36	export const LiquidGlassMorph: React.FC<LiquidGlassMorphProps> = ({
37	  left,
38	  top,
39	  width,
40	  height,
41	  duration,
42	  pathAt,
43	  reverse = false,
44	  onDone,
45	}) => {
46	  const glassRef = useRef<HTMLDivElement>(null);
47	  const shadowShapeRef = useRef<HTMLDivElement>(null);
48	  const shadowClipRef = useRef<HTMLDivElement>(null);
49	  // Lus à chaque image sans relancer l'animation quand le parent se re-rend.
50	  const pathAtRef = useRef(pathAt);
51	  pathAtRef.current = pathAt;
52	  const onDoneRef = useRef(onDone);
53	  onDoneRef.current = onDone;
54	
55	  // Layout effect : la première silhouette est posée avant le premier affichage (sinon une image
56	  // du rectangle plein clignoterait).
57	  useLayoutEffect(() => {
58	    const M = SHADOW_MARGIN;
59	    const outer = `M0 0L${width + 2 * M} 0L${width + 2 * M} ${height + 2 * M}L0 ${height + 2 * M}Z`;
60	
61	    const apply = (progress: number) => {
62	      const t = reverse ? 1 - progress : progress;
