695	                  initial={{ opacity: 0, scale: 0.95, x: -10 }}
696	                  animate={{ opacity: 1, scale: 1, x: 0 }}
697	                  exit={{ opacity: 0, scale: 0.95, x: -10 }}
698	                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
699	                >
700	                  <div 
701	                    ref={patternContentRef}
702	                    className={styles.patternPopupContent}
703	                    onScroll={handlePatternScroll}
704	                  >
705	                    <div className={styles.sectionGroup}>
706	                      <h4 className={styles.sectionTitle}>Motifs de remplissage</h4>
707	                      <ul className={styles.itemsList}>
708	                        {INFILL_PATTERNS.map((pat, pIdx) => {
709	                          const isSelected = selectedPattern === pat.name;
710	                          return (
711	                            <CustomTooltip key={pIdx} content={pat.name} description={pat.description} key-override={pat.name}>
712	                              <li 
713	                                className={clsx(styles.patternItem, { [styles.activePattern]: isSelected })}
714	                                onClick={() => {
715	                                  setSelectedPattern(pat.name);
716	                                  setIsPatternPopupOpen(false);
717	                                }}
718	                              >
719	                                <span className={styles.itemName}>{pat.name}</span>
720	                                {isSelected && <Check size={14} className="text-[#00f0ff] shrink-0" />}
721	                              </li>
722	                            </CustomTooltip>
723	                          );
724	                        })}
725	                      </ul>
726	                    </div>
727	                  </div>
728	
729	                  {hasPatternScroll && (
730	                    <div 
731	                      className={clsx(styles.externalScrollThumb, { [styles.dragging]: isPatternDragging })}
732	                      onMouseDown={handlePatternMouseDown}
733	                      style={{
734	                        height: `${patternThumbHeight}px`,
735	                        top: `${patternThumbTop}px`
736	                      }}
737	                    />
738	                  )}
739	                </motion.div>
740	              )}
741	            </AnimatePresence>
742	          </>
743	        )}
744	      </AnimatePresence>
