content.content:
1	/**
2	 * Géométrie des morphings "verre liquide" (cf. LiquidGlassMorph) : chaque fonction renvoie, pour
3	 * un instant t ∈ [0, 1], le contour SVG de la forme à cet instant, utilisé comme `clip-path:
4	 * path(...)` d'un unique élément en `backdrop-filter`. Le flou reste donc un vrai flou CSS du fond
5	 * pendant toute l'animation — contrairement à un filtre SVG "goo", dont le recontraste alpha
6	 * rend la forme opaque et remplace le flou par un aplat.
7	 *
8	 * Toutes les formes sont des contours UNIQUES et sans chevauchement (jamais deux sous-chemins
9	 * superposés), pour que la même chaîne serve aussi bien en `nonzero` qu'en `evenodd` (l'ombre
10	 * portée de LiquidGlassMorph découpe l'extérieur de la forme en `evenodd`).
11	 */
12	
13	export interface GlassRect {
14	  x: number;
15	  y: number;
16	  w: number;
17	  h: number;
18	  r: number;
19	}
20	
21	const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
22	const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
23	const round = (v: number) => Math.round(v * 100) / 100;
24	
25	const ease = {
26	  inOutSine: (t: number) => -(Math.cos(Math.PI * t) - 1) / 2,
27	  outCubic: (t: number) => 1 - Math.pow(1 - t, 3),
28	  inOutCubic: (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
29	  outBack: (t: number, s = 1.70158) => 1 + (s + 1) * Math.pow(t - 1, 3) + s * Math.pow(t - 1, 2),
30	};
31	
32	/** Chemin SVG décalé de (dx, dy) — l'ombre portée réutilise la même forme dans un repère élargi. */
33	class PathBuilder {
34	  private parts: string[] = [];
35	  private dx: number;
36	  private dy: number;
37	
38	  constructor(dx: number, dy: number) {
39	    this.dx = dx;
40	    this.dy = dy;
41	  }
42	
43	  private p(x: number, y: number) {
44	    return `${round(x + this.dx)} ${round(y + this.dy)}`;
45	  }
46	
47	  M(x: number, y: number) { this.parts.push(`M${this.p(x, y)}`); }
48	  L(x: number, y: number) { this.parts.push(`L${this.p(x, y)}`); }
49	  C(x1: number, y1: number, x2: number, y2: number, x: number, y: number) {
50	    this.parts.push(`C${this.p(x1, y1)} ${this.p(x2, y2)} ${this.p(x, y)}`);
51	  }
52	  /** Arc toujours dans le sens horaire à l'écran (sweep 1) ; rayon nul = segment droit (spec SVG). */
53	  A(rx: number, ry: number, x: number, y: number) {
54	    this.parts.push(`A${round(Math.max(0, rx))} ${round(Math.max(0, ry))} 0 0 1 ${this.p(x, y)}`);
55	  }
56	  Z() { this.parts.push('Z'); }
57	  toString() { return this.parts.join(''); }
58	}
59	
60	const cornerRadius = (r: GlassRect) => Math.max(0, Math.min(r.r, r.w / 2, r.h / 2));
61	
62	/** Renflement elliptique centré en `cx`, posé sur un bord horizontal (moignon après rupture). */
63	interface Bump {
64	  cx: number;
65	  rx: number;
66	  ry: number;
67	}
68	
69	const bumpVisible = (b?: Bump): b is Bump => !!b && b.rx > 0.3 && b.ry > 0.3;
70	
71	/** Rectangle arrondi, sens horaire, avec renflement optionnel vers le haut / vers le bas. */
72	function rectContour(b: PathBuilder, R: GlassRect, top?: Bump, bottom?: Bump) {
73	  const r = cornerRadius(R);
74	  const { x, y, w, h } = R;
75	  b.M(x + r, y);
76	  if (bumpVisible(top)) {
