97	 * part des bords horizontaux avec des congés tangents (a = demi-largeur au raccord), se resserre
98	 * jusqu'à m au milieu de l'intervalle, puis s'évase à nouveau vers B — la silhouette d'une cellule
99	 * en fin de division.
100	 */
101	function neckContour(b: PathBuilder, A: GlassRect, B: GlassRect, cx: number, a: number, m: number) {
102	  const rA = cornerRadius(A);
103	  const rB = cornerRadius(B);
104	  const yTop = A.y + A.h;
105	  const yBot = B.y;
106	  const yMid = (yTop + yBot) / 2;
107	  const gh = yMid - yTop;
108	  const k = (a - m) * 0.6;
