110	  b.M(A.x + rA, A.y);
111	  b.L(A.x + A.w - rA, A.y);
112	  b.A(rA, rA, A.x + A.w, A.y + rA);
113	  b.L(A.x + A.w, yTop - rA);
114	  b.A(rA, rA, A.x + A.w - rA, yTop);
115	  b.L(cx + a, yTop);
116	  b.C(cx + a - k, yTop, cx + m, yTop + gh * 0.45, cx + m, yMid);
117	  b.C(cx + m, yMid + gh * 0.55, cx + a - k, yBot, cx + a, yBot);
118	  b.L(B.x + B.w - rB, yBot);
119	  b.A(rB, rB, B.x + B.w, yBot + rB);
120	  b.L(B.x + B.w, yBot + B.h - rB);
121	  b.A(rB, rB, B.x + B.w - rB, yBot + B.h);
122	  b.L(B.x + rB, yBot + B.h);
123	  b.A(rB, rB, B.x, yBot + B.h - rB);
124	  b.L(B.x, yBot + rB);
125	  b.A(rB, rB, B.x + rB, yBot);
126	  b.L(cx - a, yBot);
127	  b.C(cx - a + k, yBot, cx - m, yMid + gh * 0.55, cx - m, yMid);
128	  b.C(cx - m, yTop + gh * 0.45, cx - a + k, yTop, cx - a, yTop);
129	  b.L(A.x + rA, yTop);
130	  b.A(rA, rA, A.x, yTop - rA);
131	  b.L(A.x, A.y + rA);
132	  b.A(rA, rA, A.x + rA, A.y);
133	  b.Z();
134	}
