144	 * Étirement d'un rectangle vers un autre (la pilule qui devient panneau). La hauteur dépasse
145	 * légèrement sa cible avant de s'y poser (outBack), comme une matière qui s'écoule puis se fige ;
146	 * la largeur suit avec un temps de retard.
147	 */
148	export function stretchPath(from: GlassRect, to: GlassRect, t: number, dx = 0, dy = 0) {
149	  const e = ease.inOutCubic(clamp01(t));
150	  const eh = ease.outBack(clamp01(t), 1.2);
151	  const ew = ease.inOutCubic(clamp01((t - 0.12) / 0.88));
152	  return rectPath(
153	    {
154	      x: lerp(from.x, to.x, e),
155	      y: lerp(from.y, to.y, e),
156	      w: lerp(from.w, to.w, ew),
157	      h: lerp(from.h, to.h, eh),
158	      r: lerp(from.r, to.r, e),
159	    },
160	    dx,
161	    dy,
162	  );
