177	  const yTop = A.y + A.h;
178	  const gapFinal = Bfinal.y - yTop;
179	  const gMax = Math.max(gapFinal + 26, 34);
180	
181	  // Col centré sur la partie commune des deux bords horizontaux, sans jamais empiéter sur les coins.
182	  const cx = (Math.max(A.x, Bfinal.x) + Math.min(A.x + A.w, Bfinal.x + Bfinal.w)) / 2;
183	  const straight0 = Math.max(A.x + cornerRadius(A), Bfinal.x + cornerRadius(Bfinal));
184	  const straight1 = Math.min(A.x + A.w - cornerRadius(A), Bfinal.x + Bfinal.w - cornerRadius(Bfinal));
185	  const aMax = Math.max(0, Math.min(cx - straight0, straight1 - cx));
186	  const aSplit = aMax * 0.32;
187	
188	  const h = Bfinal.h * ease.outCubic(clamp01(t / 0.55));
189	
190	  if (t < SPLIT) {
191	    const p = clamp01((t - NECK_START) / (SPLIT - NECK_START));
192	    const g = gMax * ease.inOutSine(p);
193	    const a = lerp(aMax, aSplit, ease.inOutSine(p));
194	    const m = a * (1 - Math.pow(p, 1.6));
195	    neckContour(b, A, { x: Bfinal.x, y: yTop + g, w: Bfinal.w, h, r: Bfinal.r }, cx, a, m);
196	  } else {
197	    const q = clamp01((t - SPLIT) / (1 - SPLIT));
198	    const g = lerp(gMax, gapFinal, ease.outBack(q, 2.2));
199	    const nub = 1 - ease.outCubic(clamp01(q / 0.45));
200	    const bump = { cx, rx: aSplit * 0.75, ry: (gMax / 2) * 0.7 * nub };
201	    rectContour(b, A, undefined, bump);
202	    rectContour(b, { x: Bfinal.x, y: yTop + g, w: Bfinal.w, h: Bfinal.h, r: Bfinal.r }, bump);
203	  }
204	  return b.toString();
