import puppeteer from 'puppeteer-core';
const browser = await puppeteer.launch({
  executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
  headless: 'new',
  defaultViewport: { width: 1600, height: 1000, deviceScaleFactor: 1 },
});
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:8099/', { waitUntil: 'networkidle0' });
await new Promise((r) => setTimeout(r, 2000));
const clickText = (t) => page.evaluate((t) => {
  const el = [...document.querySelectorAll('button')].find((b) => b.textContent.trim() === t);
  if (!el) return false; el.click(); return true;
}, t);
const scenario = process.argv[2];
if (scenario === 'from-prep') {
  console.log('click modeling (from prep)', await clickText('Modélisation'));
  const t0 = Date.now();
  for (const ms of [50, 200, 500, 800, 1100, 1400, 1700, 2200, 3000]) {
    await new Promise((r) => setTimeout(r, Math.max(0, ms - (Date.now() - t0))));
    await page.screenshot({ path: `mfp-${ms}.png`, clip: { x: 0, y: 60, width: 420, height: 900 } });
  }
} else {
